const fmt=(n,d=2)=>new Intl.NumberFormat('es-ES',{minimumFractionDigits:d,maximumFractionDigits:d,useGrouping:'always'}).format(n);
const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
function table(caption,heads,rows){const wrap=node('div',undefined,'table-scroll'),t=node('table'),cap=node('caption',caption),h=node('thead'),r=node('tr');heads.forEach(s=>{const c=node('th',s);c.scope='col';r.append(c);});h.append(r);const body=node('tbody');rows.forEach(row=>{const tr=node('tr');row.forEach((v,i)=>{const c=node(i?'td':'th',v);if(!i)c.scope='row';tr.append(c);});body.append(tr);});t.append(cap,h,body);wrap.append(t);return wrap;}
function section(host,title,paragraphs){const a=node('article',undefined,'card space-top prose');a.append(node('h3',title));for(const p of paragraphs)a.append(node('p',p));host.append(a);return a;}
const labels=['PSOE','PP','Vox','Frente Amplio','Podemos','SALF','ERC','Junts','EAJ-PNV','EH Bildu','CC–Primero Canarias','BNG','UPN-PP','Adelante Andalucía','Compromís–Front Valencià','Ara Més–Front Ampli','Unidad del Pueblo Canario','Teruel Existe','Soria Ya','Otro','Blanco','Nulo','No votaría','No sabe','No contesta'];
export async function initializeCookingAudit(){
 const host=document.getElementById('cooking-report');if(!host)return;
 try{const response=await fetch('./data/cooking-audit.json',{cache:'no-cache'});if(!response.ok)throw Error('HTTP '+response.status);const data=await response.json();host.replaceChildren();
const intro=section(host,'Qué he podido comprobar',[
 'Se han descargado los microdatos, cuestionarios, notas metodológicas y resultados de las dos publicaciones más recientes con ficheros accesibles: tracking Día 10 del 22/11/2026 (2.000 entrevistas) y preelectoral II del 23/11/2026 (7.500 para voto). Se han contrastado con el CIS 3587, publicado el 23/11/2026 (8.034 entrevistas). Corte de esta auditoría: 26/11/2026; no se actualiza automáticamente.',
 'Conclusión: ambos sondeos de 40dB documentan el mismo diseño y ponderación demográfica. Su estimación final incorpora una transformación adicional que el peso publicado no reproduce. Los efectos sobre PP, PSOE y Vox son parecidos, pero no hay información suficiente para demostrar que la fórmula electoral oculta sea exactamente la misma en ambos. Tampoco se puede deducir una receta única a partir de estos resultados.',
 'El CIS sí hace «cocina»: su informe técnico describe un modelo de escenarios de inercia e incertidumbre y selección de estimadores robustos. No es correcto oponer una 40dB que corrige a un CIS que publica únicamente respuestas directas. La cuestión comprobable es qué transforma cada uno y cuánto permite reconstruir su documentación.'
 ]);intro.append(node('p','Las cifras describen tratamiento estadístico, no demuestran por sí solas sesgo intencional ni capacidad predictiva. Acercarse al promedio de otros institutos tampoco valida una receta.','notice'));
 section(host,'1. Qué significa cada paso',[
 'Bruto sin ponderar: número de entrevistas que responden a cada opción, dividido por el total. Ponderado: cada entrevista cuenta según «ponde», la variable publicada por 40dB. Una respuesta de peso 1,2 aporta más que otra de 0,8. La nota metodológica explica un ajuste iterativo —raking— por sexo y edad cruzados, comunidad autónoma, tamaño del municipio y clase social. No publica en estos ficheros los objetivos y decisiones necesarios para reconstruir ese raking desde cero; aquí se aplica el peso entregado.',
 'Directa válida: se conservan candidaturas y blanco; se excluyen nulo, abstención, no sabe y no contesta. Se divide el peso de cada candidatura por el peso válido restante y se multiplica por 100. Es un cambio de denominador, no una imputación de indecisos. Estimación: cifra electoral final publicada por el instituto. Diferencia = estimación menos directa válida, en puntos porcentuales.',
 'Ejemplo: 30 respuestas para A sobre 100 personas son un 30 % de la muestra. Si solo 80 declaran voto válido, A representa el 37,5 % de ese grupo. Pasar del 30 al 37,5 no significa haber adjudicado 7,5 votos a A. Por eso comparamos la estimación con la directa válida, además de mostrar la directa sobre toda la muestra.'
 ]);
 intro.append(node('p','En móvil, desliza las tablas hacia los lados para consultar todas las columnas.','small muted'));
 const sources=section(host,'2. Muestras y comparabilidad',[
 '40dB utiliza entrevistas online CAWI del panel CINT, con cuotas y ponderación demográfica; excluye Ceuta y Melilla. El CIS utiliza entrevistas telefónicas CATI y ponderaciones publicadas para su diseño territorial. Son marcos y modos de recogida distintos: una diferencia de porcentajes puede proceder de la muestra, las preguntas, las fechas o la estimación; no puede atribuirse íntegramente a la cocina.',
 'El preelectoral II combina 2.000 entrevistas nuevas con 5.500 de tracking para el informe de voto: campo del 10 al 21 de noviembre. Su nota de 2.000 entrevistas, campo 18–20, corresponde a la recogida nueva y no sustituye la base conjunta de voto. El tracking Día 10 tiene campo 17–21. Hay solapamiento; no son dos muestras independientes.',
 'Para el CIS se utilizan las frecuencias y el cruce P10R × recuerdo 2023 del Excel oficial, con precisión completa: son tablas ya ponderadas, no entrevistas brutas sin ponderar. No se ha localizado un fichero individual descargable del 3587 en las fuentes consultadas. Por tanto, no se inventan sus recuentos sin peso ni se simula disponer de participación y simpatía unidas por persona.'
 ]);
 sources.append(table('Bases utilizadas', ['Publicación','Campo','Entrevistas','Suma de pesos','Peso mínimo–máximo'],[...data.studies.map(s=>[s.date,s.fieldwork,fmt(s.sample,0),fmt(s.weightedBase,2),fmt(s.weightMin,3)+'–'+fmt(s.weightMax,3)]),['CIS 3587 · 23/11',data.cis.fieldwork,fmt(data.cis.sample,0),fmt(data.cis.weightedBase,2),'No disponible por entrevista']]));
 for(const s of data.studies){const a=section(host,'3. 40dB · '+s.date,[
 'Porcentajes sobre toda la muestra en las dos primeras columnas; sobre voto válido declarado en la tercera; sobre voto válido estimado en la cuarta. El recuento incluye el fichero completo de voto y las 25 respuestas posibles se muestran en el detalle. Las seis candidaturas de esta tabla no suman 100: faltan otras candidaturas y blanco.',
 'PP se calcula aquí con la respuesta p2 = 2; UPN-PP (p2 = 13) se conserva aparte. Aunque el informe agrupa ambos en alguna segmentación, la gráfica directa los distingue y la gráfica de estimación no desglosa un porcentaje propio para UPN-PP. Sumarlos daría '+fmt(s.ppWithUpnValid)+' % de directa válida y una diferencia de +'+fmt(s.parties[0].estimate-s.ppWithUpnValid)+' puntos frente a la cifra publicada para PP. Se ofrecen ambas bases sin asumir una equivalencia territorial exacta; ninguna explica por sí sola la estimación. Las coaliciones territoriales se mantienen separadas de Frente Amplio.'
 ]);a.append(table('Del fichero a la estimación · '+s.date,['Candidatura','Bruto sin peso %','Directa ponderada % muestra','Directa válida %','Estimada %','Diferencia pp'],s.parties.map(p=>[p.label,fmt(p.raw),fmt(p.weighted),fmt(p.valid),fmt(p.estimate,1),(p.delta>0?'+':'')+fmt(p.delta)])));
 const detail=node('details'),summary=node('summary','Ver las 25 respuestas: recuentos y porcentajes');detail.append(summary,table('Distribución completa · '+s.date,['Respuesta','Entrevistas','Sin peso %','Ponderado % muestra'],s.all.map(r=>[labels[r.code-1],fmt(r.n,0),fmt(r.raw),fmt(r.weighted)])));a.append(detail);
 }
 const experiments=section(host,'4. ¿Basta con recuerdo, participación o indecisos?',[
 'Se han aplicado exactamente cinco reglas de prueba a ambos ficheros, sin ajustar parámetros para alcanzar los porcentajes finales. Son experimentos de esta auditoría, no métodos atribuidos a 40dB. Se compara el error medio absoluto respecto a sus seis cifras publicadas: media de las seis distancias, en puntos. Menor distancia significa mayor semejanza, no mayor acierto electoral.',
 'Corrección por recuerdo: entre 11 candidaturas identificables en ambos cuestionarios y los resultados definitivos de 2023, factor = cuota real dentro del conjunto comparable / cuota recordada ponderada en ese mismo conjunto. Se multiplica por él todo el peso de cada grupo. Resto de recuerdos, nuevos electores y ausencia de recuerdo mantienen factor 1. No se fuerza abstención ni se devuelve a nadie a su antiguo partido. Se incluyen votos CERA en la referencia oficial, mientras la encuesta se refiere a residentes: es una limitación del experimento.',
 'Participación lineal: se multiplica además por p1/10 para respuestas de 0 a 10; desconocidos conservan peso. Reparto NS/NC: se distribuye todo su peso como los decididos con el mismo recuerdo; si ese grupo no tiene decididos, se utiliza la distribución general. Abstención y nulo no se reparten. La última regla usa primero simpatía p3 cuando designa una candidatura y reparte el resto por recuerdo. No hay suavizado ni calibración posterior.'
 ]);
 experiments.append(table('Distancia media a la estimación publicada · seis candidaturas',['Experimento propio','22/11 · pp','23/11 · pp'],data.studies[0].models.map((m,i)=>[m.label,fmt(m.mae,3),fmt(data.studies[1].models[i].mae,3)])));
 const det=node('details');det.append(node('summary','Ver porcentajes obtenidos por cada regla'));for(const s of data.studies)det.append(table('Reglas propias · '+s.date,['Regla',...s.parties.map(p=>p.label)],s.models.map(m=>[m.label,...m.values.map(v=>fmt(v))])));experiments.append(det);
 experiments.append(node('p','Ninguna de las cinco reglas reproduce las seis estimaciones con su precisión publicada. No basta con decir «40dB corrige el recuerdo»: la ponderación por recuerdo simple no identifica su procedimiento. Puede intervenir calibración conjunta, modelos de participación o imputación distintos, información adicional u otras decisiones. Los archivos examinados no permiten elegir entre esas posibilidades.'));
 const recall=section(host,'5. Qué sugiere el recuerdo y qué no demuestra',[
 'El recuerdo ponderado presenta más PSOE que PP en ambos ficheros. En nuestra prueba, corregirlo reduce el peso del grupo que recuerda PSOE y eleva el de PP. La tabla muestra factores muy parecidos entre publicaciones; no son pesos electorales entregados por 40dB. El recuerdo puede ser erróneo y cambia con el tiempo: corregirlo mecánicamente también puede introducir error.',
 'El efecto final es similar para PP, PSOE y Vox; no es una multiplicación uniforme para todas las candidaturas. Frente Amplio pasa de quedar ligeramente por debajo de su directa válida a situarse ligeramente por encima. Esto no prueba que hayan cambiado de algoritmo: una misma regla, aplicada a otras respuestas, puede producir efectos distintos. Conclusión sobre «misma cocina»: mismo marco documentado; identidad de la fórmula final no demostrable.'
 ]);recall.append(table('Recuerdo ponderado y factores de nuestro experimento',['Recuerdo 2023','22/11 · % muestra','23/11 · % muestra','Factor 22/11','Factor 23/11'],['psoe','pp','vox','sumar'].map(id=>{const a=data.studies[0].recall.find(x=>x.party===id),b=data.studies[1].recall.find(x=>x.party===id);return [id.toUpperCase(),fmt(a.weighted),fmt(b.weighted),fmt(a.factor,3),fmt(b.factor,3)];})));
 const c=data.cis,compare=section(host,'6. El CIS del 23 de noviembre: su cocina y sus resultados',[
 'El informe técnico del estudio 3587 describe un modelo bifactorial de inercia e incertidumbre: genera escenarios de apoyo electoral, compara media, mediana y estimadores robustos y evalúa estabilidad mediante remuestreo. La tabla de la página 8 recomienda la media aritmética para las seis candidaturas aquí comparadas. Su anexo, páginas 200–202, contiene una matriz de escenarios; esas filas no son personas entrevistadas.',
 'Esta documentación permite conocer la arquitectura y los escenarios resultantes, pero no basta para reconstruir de forma única el paso de cada entrevista a cada escenario. No equiparamos ese modelo con la corrección por recuerdo de la app. En «CIS · Estimación alternativa» se calculan reglas propias y una combinación opcional con otras encuestadoras: ninguna de esas dos cifras es la receta oficial del CIS.',
 'Aquí la estimación procede del anexo oficial de estimación; la intención directa, del Excel de resultados. Los NS ponderados son '+fmt(c.ns)+' % y los NC '+fmt(c.nc)+' %: no se trata de un pequeño residuo. El bruto sin ponderar del CIS no está disponible en los materiales utilizados.'
 ]);compare.append(table('CIS 3587 · bases y transformación',['Candidatura','Directa ponderada % muestra','Directa válida %','Estimada oficial %','Diferencia pp'],c.parties.map(p=>[p.label,fmt(p.weighted),fmt(p.valid),fmt(p.estimate,1),(p.delta>0?'+':'')+fmt(p.delta)])));
 compare.append(node('p','Discrepancias de las fuentes que se conservan: el PP directo es 18,0466 % en el Excel y 18,0 % redondeado en frecuencias, frente al 18,2 % del anexo de estimación. Además, el informe técnico (p. 8) recomienda 24,4 % al PP, mientras el anexo oficial publica 24,7 %. No se ha encontrado una explicación que reconcilie ambas cifras: para la comparación se mantiene 24,7 %, sin ocultar 24,4 %.','notice'));
 compare.append(table('Comparación con idéntico cambio de denominador',['Transformación sobre directa válida','40dB 22/11 · pp','40dB 23/11 · pp','CIS 23/11 · pp'],c.parties.map((p,i)=>[p.label,fmt(data.studies[0].parties[i].delta),fmt(data.studies[1].parties[i].delta),fmt(p.delta)])));
 section(host,'7. Cómo interpretar la diferencia entre institutos',[
 'En el sondeo más reciente, la cifra estimada de PP de 40dB supera su directa válida en 6,53 puntos tomando PP solo y en 6,31 sumando UPN-PP; el CIS eleva PP 1,70. Para PSOE, los cambios son −2,31 y −1,82; para Vox, −2,57 y +0,77. El CIS no se limita a aumentar a PSOE: respecto a la conversión simple a voto válido, lo reduce. Otra cosa es que su estimación final de PSOE sea mayor que la de 40dB, porque parten de muestras diferentes.',
 'La diferencia verificable de cocina es, por tanto, doble: resultados de la transformación distintos y documentación distinta. 40dB entrega microdatos con peso demográfico, pero los documentos examinados no detallan su fórmula electoral completa; el CIS explica un modelo de escenarios y publica su matriz, aunque no hemos podido reproducir su construcción desde entrevistas individuales. No se atribuye a ninguno una imputación concreta que no esté acreditada.',
 'Para demostrar si la receta exacta de 40dB se repite harían falta la especificación de la estimación, objetivos de calibración, reglas de participación e imputación y, si procede, sus coeficientes y versión. Reproducir unas cifras mediante factores elegidos después de conocerlas sería ajustar una fórmula a los resultados, no descubrir cómo los produjeron. Esta auditoría mantiene esa diferencia.'
 ]);
 const final=section(host,'8. Fuentes, descarga y reproducción',[
 'Los ZIP públicos permiten obtener DTA, XLSX, cuestionarios y notas. Se ha usado el fichero de voto de 7.500 registros del preelectoral, no el fichero temático de 2.000. Se han comprobado tamaño, códigos, pesos y distribución directa frente a las cifras redondeadas de los informes. Los recuentos sin peso suman la muestra y los porcentajes ponderados completos suman 100.',
 'El archivo de auditoría contiene agregados, factores, reglas ensayadas, huellas SHA-256 y fuentes. Los identificadores y las filas individuales no se copian a esta web. Para repetir los cálculos desde las descargas originales se conserva el script scripts/prepare-cooking-audit.mjs en el proyecto. El informe no modifica el promedio ni la proyección de escaños y no sustituye los estudios del Laboratorio de microdatos.'
 ]);
 const list=node('ul');for(const s of data.studies)for(const [label,url]of [['40dB '+s.date+' · ZIP de datos',s.archive.url],['40dB '+s.date+' · informe de voto',s.report.url]]){const li=node('li'),a=node('a',label);a.href=url;a.target='_blank';a.rel='noopener noreferrer';li.append(a);list.append(li);}
 for(const [label,url]of [['CIS 3587 · Excel oficial',c.source],['CIS 3587 · frecuencias y ficha técnica','https://www.cis.es/documents/d/guest/es3587mar_a-pdf'],['CIS 3587 · estimación publicada','https://www.cis.es/documents/d/guest/3587_estimacion-pdf'],['CIS 3587 · informe técnico',c.technicalReport.url],['Resultados definitivos 2023 · BOE',data.reference.url],['Descargar agregados y reglas de la auditoría','./data/cooking-audit.json']]){const li=node('li'),a=node('a',label);a.href=url;if(url.startsWith('https:')){a.target='_blank';a.rel='noopener noreferrer';}else a.download='auditoria-cocina-20261126.json';li.append(a);list.append(li);}final.append(list);
 }catch(e){host.replaceChildren(node('p','No se puede cargar la auditoría: '+e.message+'. Vuelve a cargar la página.','notice'));}
}
